MATCH (v:Vehicle)-[:INVOLVED_IN]->(c:Crime)-[:INVESTIGATED_BY]->(o:Officer)
WHERE v.model = "S8" AND c.last_outcome = "Investigation complete; no suspect identified"
  AND EXISTS {
    MATCH (o)<-[:INVESTIGATED_BY]-(c2:Crime)<-[:PARTY_TO]-(p:Person)
  }
RETURN DISTINCT v.reg

MATCH (o:Officer {rank: "Inspector"})<-[:INVESTIGATED_BY]-(c:Crime {last_outcome: "Investigation complete; no suspect identified"})-[:OCCURRED_AT]->(l:Location)<-[:OCCURRED_AT]-(c2:Crime)-[:INVOLVED_IN]->(:Vehicle)
WHERE EXISTS {
  MATCH (c3:Crime {date: "28/08/2017"})-[:OCCURRED_AT]->(l)
}
RETURN DISTINCT o.name

MATCH (p:Person)-[:FAMILY_REL]->(m:Person)
WHERE m.name = "Matthew"
  AND EXISTS {
    MATCH (p)-[:PARTY_TO]->(:Crime)-[:INVESTIGATED_BY]->(:Officer)
  }
RETURN DISTINCT p.nhs_no

MATCH (l:Location)
WHERE EXISTS {
  MATCH (c1:Crime)-[:OCCURRED_AT]->(l),
        (c1)-[:INVESTIGATED_BY]->(o:Officer)
  WHERE o.name = "Scjon"
}
AND EXISTS {
  MATCH (c2:Crime)-[:OCCURRED_AT]->(l),
        (v:Vehicle)-[:INVOLVED_IN]->(c2)
  WHERE v.year = "2011"
}
RETURN DISTINCT l.address

MATCH (p:Person)-[:KNOWS]->(k:Person)-[:CURRENT_ADDRESS]->(l:Location)
WHERE k.surname = "Carr"
  AND NOT EXISTS {
    MATCH (k)-[:FAMILY_REL]->(f:Person)
  }
  AND NOT EXISTS {
    MATCH (k)-[:CURRENT_ADDRESS]->(l2:Location)
    WHERE l2.address = l.address
  }
  AND l.postcode = "BL1 1LE"
RETURN DISTINCT p.name

MATCH (target:Crime)-[:OCCURRED_AT]->(loc:Location)-[:LOCATION_IN_AREA]->(:Area {areaCode: "M1"})
WHERE target.date IS NOT NULL
  AND EXISTS {
    MATCH (qualifying:Crime)-[:OCCURRED_AT]->(loc)
    WHERE qualifying.last_outcome = "Investigation complete; no suspect identified"
      AND EXISTS {
        MATCH (:Vehicle {model: "Prius Plug-in"})-[:INVOLVED_IN]->(qualifying)
      }
  }
WITH target
ORDER BY target.date ASC
LIMIT 1
RETURN target.date
